defmodule Tymeslot.Repo.Migrations.DropAvailabilityScheduleBufferMinutesTest do
  @moduledoc """
  Covers the contract migration that drops `availability_schedules.buffer_minutes`
  after the split into `buffer_before_minutes` and `buffer_after_minutes`.
  See `Tymeslot.Test.MigrationRunner`.
  """

  use Tymeslot.DataCase, async: false

  @moduletag :database
  @moduletag :availability
  @moduletag :migrations

  alias Tymeslot.Repo
  alias Tymeslot.Test.MigrationRunner

  # Generated by `mix ecto.gen.migration drop_availability_schedule_buffer_minutes`.
  @version 20_261_012_214_211

  test "drops the old buffer column" do
    MigrationRunner.down!(@version)
    assert old_column_present?()

    MigrationRunner.up!(@version)

    refute old_column_present?()
  end

  # A schedule written through a rolled-back image has a newer old buffer
  # than its pair, but nothing can tell it from a merely stale one, so the
  # pair must survive as it is rather than be refreshed from the old column.
  test "leaves the before/after pair as it is, whatever the old column holds" do
    schedule = insert(:availability_schedule, buffer_before_minutes: 5, buffer_after_minutes: 40)
    MigrationRunner.down!(@version)

    Repo.query!("UPDATE availability_schedules SET buffer_minutes = 90 WHERE id = $1", [
      schedule.id
    ])

    MigrationRunner.up!(@version)

    assert buffers_of(schedule.id) == {5, 40}
  end

  test "rolling back restores the old buffer as the larger of the two" do
    schedule = insert(:availability_schedule, buffer_before_minutes: 10, buffer_after_minutes: 40)
    flipped = insert(:availability_schedule, buffer_before_minutes: 60, buffer_after_minutes: 0)

    MigrationRunner.down!(@version)

    assert old_buffer_of(schedule.id) == 40
    assert old_buffer_of(flipped.id) == 60
  end

  test "rolling back gives a schedule inserted afterwards the old default of 15" do
    profile = insert(:profile)
    MigrationRunner.down!(@version)

    %{rows: [[id]]} =
      Repo.query!(
        """
        INSERT INTO availability_schedules (profile_id, name, inserted_at, updated_at)
        VALUES ($1, 'Rollback', now(), now())
        RETURNING id
        """,
        [profile.id]
      )

    assert old_buffer_of(id) == 15
  end

  defp old_column_present? do
    %{rows: [[count]]} =
      Repo.query!("""
      SELECT COUNT(*) FROM information_schema.columns
      WHERE table_name = 'availability_schedules' AND column_name = 'buffer_minutes'
      """)

    count == 1
  end

  defp old_buffer_of(id) do
    %{rows: [[buffer]]} =
      Repo.query!("SELECT buffer_minutes FROM availability_schedules WHERE id = $1", [id])

    buffer
  end

  defp buffers_of(id) do
    %{rows: [[buffer_before, buffer_after]]} =
      Repo.query!(
        "SELECT buffer_before_minutes, buffer_after_minutes FROM availability_schedules WHERE id = $1",
        [id]
      )

    {buffer_before, buffer_after}
  end
end
